/* ============================================================================
   ⭐ attachSwipe — THE ONE GESTURE ARBITER BOTH PHONE CAROUSELS USE. 11 Aug 2026.
   ⛔ PHONE ONLY. Every caller gates it on the same CSS-declared phone test it already uses
   (`revSolo()` / `--hxMode`), so this adds no second opinion about what a phone is (D93).

   ⭐ WHY IT EXISTS. Two separate faults, one cause.
   1. The review swipe "did not work" on the client's iPhone, having passed its own tests, which
      synthesised touch events (D94's lesson, again). With `touch-action:pan-y` the BROWSER
      decides at the first movement whether the gesture is a scroll; a swipe with any real
      vertical component is taken as one, the page slides and the belt never moves. Nothing in
      the handler is reachable at that point — it is not a handler bug, it is a bug about who
      owns the gesture.
   2. The helix's drag was bound `{passive:true}` with no `touch-action` at all, so a diagonal
      drag spun the spiral AND scrolled the page at the same time. Client: "as I'm swiping it
      diagonally down or diagonally up, the screen is also moving diagonally… the screen
      basically stays still unless they're swiping directly up or directly down."

   ⭐ SO THE PAGE IS TAKEN OUT OF THE ARGUMENT: `touch-action:none` on the element, one axis
   decided once at 5px, and NOTHING moves on the axis we did not pick.
   ⛔ THE PRICE, AND IT IS DELIBERATE: `touch-action:none` also stops the NATIVE vertical scroll
   over that element, so a near-vertical drag is scrolled by hand here — 1:1 while the finger is
   down, then a decaying glide so a flick still coasts. That is the client's "unless they're
   swiping directly up or directly down". ⚠️ A future change that drops the pass-through, or the
   glide, strands the customer's finger on a dead patch of screen. Test by scrolling THROUGH the
   section with a finger on the cards, not past it.

   ⚠️ POINTER EVENTS, NOT touch + mouse SIDE BY SIDE. One path covers finger, trackpad-click-drag
   and mouse, which is what D94 had to bolt on afterwards. ⚠️ A trackpad's two-finger SWIPE is
   still a `wheel` with deltaX and fires none of this — each caller keeps its own wheel handler.
   ⚠️ Move and up are on the WINDOW, and the pointer is captured, so a drag that leaves the
   element still finishes (D94) instead of sticking with the button already up.
   ============================================================================ */
function attachSwipe(el,opts){
  if(!el)return;
  const SLOP=5;                       // px of travel before the gesture commits to one axis
  const cfg=Object.assign({enabled:()=>true,ignore:null,onStart:null,onMove:null,onEnd:null},opts||{});
  let on=false,axis=0,pid=null,touch=false,sx=0,sy=0,ly=0,lt=0,glide=null,freed=false;
  /* ⛔ THE RELEASE SPEED IS MEASURED OVER A TIME WINDOW, NOT OVER THE LAST TWO EVENTS — D112.
     `vy=step/dt` with dt floored at 1ms read whatever the final pair happened to be, and a
     phone delivers pointermove every 4–8ms, so one ordinary sample became 5px/ms and the glide
     that followed was enormous: measured, a 40px flick — "my thumb barely moving" — threw the
     page 309px. ⭐ Averaging over the last VY_WIN ms is also what makes a pause-then-lift
     behave: hold still for a moment before letting go and the window shows no travel, so there
     is no fling, which is exactly what every native scroller does and what a customer expects
     when they stop to read something. */
  const VY_WIN=70;                 // ms of history the release speed is averaged over
  let vyHist=[];                   // {y,t} samples, trimmed to VY_WIN
  let lx=0,lxt=0,vx=0;                          // horizontal speed, px/ms — see the flick note in end()

  /* ⛔ `html` CARRIES `scroll-behavior:smooth` FOR THE NAV'S ANCHOR JUMPS, AND IT POISONS A
     HAND-ROLLED SCROLL. Every scrollBy would then ANIMATE toward its target, and sixty of them a
     second each restart from where the last animation had got to — measured, 120px of finger
     travel moved the page 45. The finger would slide and the page would lag behind it, which is
     worse than the native scroll this replaces. An inline `auto` outranks the stylesheet for as
     long as the gesture owns the page, and is taken off again once it lets go.
     ⚠️ Put it back AFTER the glide, not on pointerup — the glide is scrollBy too. */
  const freeScroll=()=>{ if(!freed){freed=true;document.documentElement.style.scrollBehavior='auto';} };
  const restoreScroll=()=>{ if(freed){freed=false;document.documentElement.style.scrollBehavior='';} };
  const stopGlide=()=>{ if(glide!==null){cancelAnimationFrame(glide);glide=null;} restoreScroll(); };

  /* ⛔ A GLIDE THE CUSTOMER CANNOT STOP IS WHAT "IT JUST JUMPS BETWEEN SECTIONS" IS — D112,
     11 Aug 2026. `stopGlide()` used to be reachable only from a `pointerdown` ON THE STAGE, so
     the one thing everybody does to halt a moving page — put a thumb down anywhere — did
     nothing here. Measured: 406px of further travel AFTER the touch. Worse, the native scroll
     that touch then starts runs AT THE SAME TIME as the glide still scrolling by hand, and the
     two fight over `window.scrollTop` sixty times a second. That is not a feel problem, it is
     two things driving one number.
     ⚠️ Bound on the WINDOW in the CAPTURE phase so nothing downstream can swallow it, and
     `touchstart` as well as `pointerdown` because a browser that fires touch events late would
     otherwise get a frame or two of the fight. ⚠️ `wheel` too, for the trackpad. */
  const killGlide=()=>{ if(glide!==null) stopGlide(); };
  window.addEventListener('pointerdown',killGlide,{capture:true,passive:true});
  window.addEventListener('touchstart',killGlide,{capture:true,passive:true});
  window.addEventListener('wheel',killGlide,{capture:true,passive:true});

  el.addEventListener('pointerdown',e=>{
    if(!cfg.enabled())return;
    if(e.pointerType==='mouse'&&e.button!==0)return;
    if(cfg.ignore&&cfg.ignore(e.target))return;
    stopGlide();
    on=true;axis=0;pid=e.pointerId;touch=e.pointerType!=='mouse';
    sx=e.clientX;sy=e.clientY;ly=e.clientY;lt=e.timeStamp||performance.now();
    vyHist=[{y:e.clientY,t:lt}];                 // D112: fresh window per gesture
    lx=e.clientX;lxt=lt;vx=0;
  });

  window.addEventListener('pointermove',e=>{
    if(!on||e.pointerId!==pid)return;
    const dx=e.clientX-sx,dy=e.clientY-sy;
    /* ⚠️ DECIDE ONCE. Re-deciding every frame makes a diagonal drag flicker between turning the belt
       and scrolling the page — the same rule the touch path already had. Ties go to the
       carousel: a drag that is exactly diagonal is a swipe, which is the client's ask. */
    if(!axis){
      if(Math.abs(dx)<SLOP&&Math.abs(dy)<SLOP)return;
      axis=Math.abs(dx)>=Math.abs(dy)?1:-1;
      if(axis>0){ try{el.setPointerCapture(pid);}catch(_){} if(cfg.onStart)cfg.onStart(); }
    }
    if(axis>0){
      if(e.cancelable)e.preventDefault();       // stops the text under the finger being selected
      /* speed is kept over the LAST pair of events, not over the whole gesture: a flick that
         starts slowly and ends fast is a flick, and averaging from the start would call it a
         drag. Smoothed a little so one stray frame cannot decide it. */
      const nx=e.timeStamp||performance.now(),dt2=Math.max(1,nx-lxt);
      vx=0.6*((e.clientX-lx)/dt2)+0.4*vx;
      lx=e.clientX;lxt=nx;
      if(cfg.onMove)cfg.onMove(dx);
      return;
    }
    /* the pass-through. ⚠️ A MOUSE gets none of it: dragging a mouse down a page has never
       scrolled it, and doing so here would make an ordinary click-drag feel broken. */
    if(!touch)return;
    freeScroll();
    const now=e.timeStamp||performance.now(),step=e.clientY-ly;
    ly=e.clientY;lt=now;
    vyHist.push({y:e.clientY,t:now});
    while(vyHist.length>2&&now-vyHist[0].t>VY_WIN) vyHist.shift();
    window.scrollBy(0,-step);
  },{passive:false});

  /* the speed the finger actually left at, averaged over the last VY_WIN ms (see the note by
     the declaration). Returns 0 when the finger was resting, which suppresses the fling. */
  function releaseSpeed(){
    if(vyHist.length<2) return 0;
    const a=vyHist[0], b=vyHist[vyHist.length-1], dt=b.t-a.t;
    return dt>4 ? (b.y-a.y)/dt : 0;
  }
  /* ⛔ DECAY 0.90, NOT 0.94, AND A LOWER CAP — D112. Total travel is v0/(1-decay), so 0.94 was
     spending 16.7 frames' worth of the launch speed and 0.90 spends 10 — the difference between
     a flick crossing a viewport and a half and a flick crossing a third of one.
     ⚠️ Do not read this as "less momentum is better": with no glide at all the page stops dead
     under the finger and feels stuck. It is meant to land near what the platform does. */
  function fling(){
    stopGlide();                                 // ⛔ never let two glides run at once: each
                                                 // re-registers its own rAF, so a second would
                                                 // not replace the first, it would ADD to it
    let v=Math.max(-2.6,Math.min(2.6,releaseSpeed()))*16.7;   // px/ms → px per 60Hz frame, capped
    freeScroll();                                // the glide is scrollBy too — smooth would poison it
    const step=()=>{
      v*=0.90;
      if(Math.abs(v)<0.4){glide=null;restoreScroll();return;}
      window.scrollBy(0,-v);
      glide=requestAnimationFrame(step);
    };
    glide=requestAnimationFrame(step);
  }
  function end(e){
    if(!on||(e&&e.pointerId!==pid))return;
    on=false;
    try{el.releasePointerCapture(pid);}catch(_){}
    /* ⭐ THE RELEASE CARRIES ITS SPEED, NOT JUST ITS DISTANCE — 11 Aug 2026. Client: "when I try
       and swipe quickly on the reviews, it's not letting me swipe quickly."
       ⛔ A DISTANCE-ONLY THRESHOLD PUNISHES THE FASTEST GESTURE. A deliberate 100px drag paged
       fine; a quick flick — which on a phone is often 25–40px of travel before the finger leaves
       the glass — fell under the 48px throw and rolled straight back, so the control read as
       ignoring exactly the input a confident user reaches for. The caller decides what counts;
       this just hands it both numbers. */
    if(axis>0){ if(cfg.onEnd)cfg.onEnd(e?e.clientX-sx:0,vx); }
    else if(axis<0&&touch&&Math.abs(releaseSpeed())>0.25){ fling(); }
    else restoreScroll();
    axis=0;pid=null;
  }
  window.addEventListener('pointerup',end);
  window.addEventListener('pointercancel',end);
}

